variables_css:
:root {
  /* Colors */
  --color-ink: #14171f;
  --color-paper: #ffffff;
  --color-mist: #f5f6f9;
  --color-hairline: #e5e7eb;
  --color-slate: #677084;
  --color-fog: #9ba2b0;
  --color-graphite: #373f51;
  --color-charcoal: #222834;
  --color-deep-ink: #050505;
  --color-pearl: #d0d4dc;
  --color-iris: #6a57e3;
  --color-lilac: #ddd8ff;
  --color-orchid: #cd74dd;
  --color-wine: #45192f;
  --color-coral: #ff5a5e;
  --color-lime: #f0fb96;
  --color-hero-wash: #9ddef9;
  --gradient-hero-wash: linear-gradient(90deg, rgb(205, 243, 253), rgb(157, 222, 249) 42.88%, rgb(151, 157, 241) 94.62%);

  /* Typography — Font Families */
  --font-gt-standard-m: 'GT Standard M', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-gt-standard-l: 'GT Standard L', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

theme_css:
@theme {
  /* Colors */
  --color-ink: #14171f;
  --color-paper: #ffffff;
  --color-mist: #f5f6f9;
  --color-hairline: #e5e7eb;
  --color-slate: #677084;
  --color-fog: #9ba2b0;
  --color-graphite: #373f51;
  --color-charcoal: #222834;
  --color-deep-ink: #050505;
  --color-pearl: #d0d4dc;
  --color-iris: #6a57e3;
  --color-lilac: #ddd8ff;
  --color-orchid: #cd74dd;
  --color-wine: #45192f;
  --color-coral: #ff5a5e;
  --color-lime: #f0fb96;
  --color-hero-wash: #9ddef9;

  /* Typography */
  --font-gt-standard-m: 'GT Standard M', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-gt-standard-l: 'GT Standard L', ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
}

