    {
      "name": "Pill Tag / Filter Chip",
      "role": "Removable filter or category marker",
      "description": "16–40px radius, Mist background, Ink 14px text, 4–8px vertical / 12px horizontal padding. Optional close × in Slate. Used for selected filters, role tags, and the segmented switcher."
