  "elevation": [
    {
      "style": "rgba(34, 40, 52, 0.05) 0px 4px 10px 0px, rgba(34, 40, 52, 0.04) -2px 18px 18px 0px",
      "element": "Primary Filled Button"
    },
    {
      "style": "rgb(19, 24, 25) 0px 1px 3px 0px inset",
      "element": "Active Segmented Tab"
